    r"^[一二三四五六七八九十]+\s*[、.．].*共\s*\d+(?:\.\d+)?\s*分"
)


def _strip_trailing_section_titles(content: str) -> str:
    lines = content.split("\n")
    while lines and _EXAM_SECTION_TITLE_RE.match(lines[-1].strip()):
