"""会话 10b：逐单元格数行框（Range.getClientRects），确认目标列单行。"""
from playwright.sync_api import sync_playwright

LEARNER = "10b验收同学011227"

JS = """
() => {
  const rows = [...document.querySelectorAll(
      '#memory-area .card:nth-of-type(2) table tr')];
  const out = [];
  for (const tr of rows) {
    const cells = [...tr.children];
    const lineCounts = cells.map(td => {
      const r = document.createRange();
      r.selectNodeContents(td);
      return r.getClientRects().length;
    });
    out.push({texts: cells.map(c => c.innerText.split('\\n')[0].slice(0, 14)),
              lines: lineCounts});
  }
  return out;
}
"""

with sync_playwright() as p:
    browser = p.chromium.launch(channel="chrome")
    page = browser.new_page(viewport={"width": 1440, "height": 900})
    page.goto("http://127.0.0.1:18800/memory.html?source=auto")
    page.fill("#learner-input", LEARNER)
